quests[10464] = { id = 10464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gelöbnis des Weisen", description = "Ihr habt Euer Versprechen gegeben, {class}. Jetzt liegt es an Euch, es einzuhalten.\n\nDient den Wächtern der Sande wohl, und Ihr werdet Euren Lohn erhalten.\n\nWenn Ihr scheitert, wird die Zeitlinie, wie wir sie kennen, zerrissen werden!", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt.", progress = "Ihr leistet uns weiterhin gute Dienste, {name}.", completion = "Ihr habt Euch als würdig erwiesen, {race}. Zumindest bis zu einem gewissen Punkt.\n\nDie Gunst der Hauptgefährtin Nozdormus ist nicht so leicht zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
