quests[10471] = { id = 10471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur des Verteidigers", description = "Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, {name}. Und dafür steht Euch die gebührende Anerkennung zu.\n\nWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Ihr seid zurück. Möchtet Ihr mit mir sprechen?", completion = "Ihr seid in der Tat ein würdiger Verbündeter. Und je mächtiger Ihr werdet, desto mächtiger wird auch das Band der Ewigkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[10472] = { id = 10472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bündnis des Weisen", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, {name}.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Möge die Zeit immer mit Euch sein, {name}.", completion = "Ihr gehört zur Zeit, {name}. Ihr gehört zu uns.\n\nSchaut! Sogar aus diesem kleinen Rest aus den Brunnen der Ewigkeit strömt noch Macht, die kein sterbliches Wesen begreifen kann.\n\nNehmt dieses Geschenk an, auf dass alle von Eurem Bündnis mit den Wächtern der Zeit erfahren... auf dass alle von Eurem Bündnis mit der Zeit selbst erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10473] = { id = 10473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bündnis des Bewahrers", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, {name}.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Möge die Zeit immer mit Euch sein, {name}.", completion = "Ihr gehört zur Zeit, {name}. Ihr gehört zu uns.\n\nSchaut! Sogar aus diesem kleinen Rest aus den Brunnen der Ewigkeit strömt noch Macht, die kein sterbliches Wesen begreifen kann.\n\nNehmt dieses Geschenk an, auf dass alle von Eurem Bündnis mit den Wächtern der Zeit erfahren... auf dass alle von Eurem Bündnis mit der Zeit selbst erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10474] = { id = 10474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bündnis des Helden", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, {name}.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", progress = "Möge die Zeit immer mit Euch sein, {name}.", completion = "Ihr gehört zur Zeit, {name}. Ihr gehört zu uns.\n\nSchaut! Sogar aus diesem kleinen Rest aus den Brunnen der Ewigkeit strömt noch Macht, die kein sterbliches Wesen begreifen kann.\n\nNehmt dieses Geschenk an, auf dass alle von Eurem Bündnis mit den Wächtern der Zeit erfahren... auf dass alle von Eurem Bündnis mit der Zeit selbst erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[10475] = { id = 10475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bündnis des Verteidigers", description = "Eurer Errungenschaften haben meine Erwartungen weit übertroffen, {name}.\n\nIhr taucht so behände in die Zeit hinein und wieder heraus, wie ein Bronzedrachen. Euch ist große Macht vorherbestimmt, und ich bin mehr als erfreut, Euch auf Eurem Weg dorthin zu unterstützen.\n\nDient weiterhin den Wächtern der Sande, dann werde ich die volle Macht Eures Geschenks erwecken.", sourceObjective = "Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[10476] = { id = 10476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmige Feinde", description = "Wenn Ihr Eure Treue uns gegenüber beweisen wollt, dann gibt es keinen besseren Weg, als unsere Feinde zu bekämpfen.\n\nUnter diesen Feinden gibt es keinen, der so stark und so wild ist, wie die Oger. Bringt mir die Kriegsperlen, die sie um den Hals tragen, als Beweis für ihr Ableben. Wenn Ihr das tut, lasse ich die anderen von Eurem Heldenmut wissen.", sourceObjective = "Aufseher Moi'bff Jill in Telaar möchte, dass Ihr 10 Obsidiankriegsperlen von den verschiedenen Ogern in Nagrand besorgt.", progress = "Nun, {name}? Könnt Ihr nur Reden schwingen, oder habt Ihr mir etwas vorzuweisen?", completion = "Ihr beweist Euch allmählich als wertvoller Verbündeter und Kämpfer. Macht weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[10477] = { id = 10477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Kriegsperlen", progress = "Habt Ihr noch mehr Obsidiankriegsperlen dabei, {name}?", completion = "Ihr beweist Euch weiterhin als wertvoll, {name}. Möge Eure Stärke nie versagen." }
quests[10478] = { id = 10478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Kriegsperlen!", progress = "Habt Ihr noch mehr Obsidiankriegsperlen besorgt, {name}?", completion = "Ihr beweist uns auch weiterhin Eure Stärke und Ehre, {name}." }
quests[10479] = { id = 10479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke beweisen", description = "Auch wenn wir ein friedvolles Leben suchen, haben wir doch viele Feinde.\n\nUnter diesen Feinden gibt es keinen, der so viel rohe Macht besitzt, wie die Oger. Wenn Ihr uns Euren Heldenmut beweisen wollt, bringt mir die Kriegsperlen, die sie um den Hals tragen. Wenn Ihr das tut, lasse ich die anderen von Euren Taten wissen.", sourceObjective = "Aufseher Bullrok in Garadar möchte, dass Ihr 10 Obsidiankriegsperlen von den verschiedenen Ogern in Nagrand besorgt.", progress = "Habt Ihr etwas, das Ihr mir zeigen möchtet, {name}?", completion = "Ihr seid wirklich ein starker Verbündeter, {name}. Den Ogern der Scherbenwelt Auge in Auge gegenüberzutreten ist nichts, was jeder einfach so tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10480] = { id = 10480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister des Wassers", description = "Die Naga der Illidari in dieser Gegend haben die Kontrolle über die einzige reine Wasserversorgung im Schattenmondtal an sich gerissen.\n\nDirekt nördlich von hier findet Ihr das Nest der Naga, die Echsennarbe. Um die Echsennarbe herum findet Ihr Ansammlungen von tosendem Wasser, die ihre Qual ins Land hinausschreien. Bei diesen Ansammlungen streifen die wütenden Geister des Wassers umher.\n\nReist zur Echsennarbe und benutzt das Totem der Geister, um ihre Wasserseelen einzufangen. Die größte Ansammlung dieser Geister findet Ihr in der Nähe der Zisterne der Echsennarbe.", sourceObjective = "Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 5 Wasserseelen einzufangen.", progress = "Wo auch immer Ihr die Naga findet, könnt Ihr sicher auch die gequälten Wassergeister finden.", completion = "Und zurück bleibt nichts als Luft, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10481] = { id = 10481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wütende Geister der Luft", description = "Begebt Euch nach Südosten, Held. Wenn Ihr große blaue Kristalle aus dem Boden herausragen seht, habt Ihr Euer Ziel erreicht. Dort, auf den Netherschwingenfeldern, werdet Ihr die wütenden Geister der Luft finden. Sie streifen rings um die Felder auf den Klippen und um die Berge herum umher.\n\nZerstört ihre gequälten Körper und fangt ihre Seelen im Totem der Geister ein. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 10 Luftseelen einzufangen.", progress = "Bald werden wir mit den Geistern sprechen.", completion = "Erlaubt mir, dass ich Euch für diese wagemutige Tat belohne, Held.\n\nJetzt müssen wir uns an die Arbeit machen! Bitte tretet zurück, damit ich das Totem aufstellen und die Seelen freilassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[10482] = { id = 10482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plünderer der Höllenorcs", description = "Plünderer, Orcs des Knochenmalmerklans, treiben sich bei den zerstörten Kriegsmaschinerien am Pfad des Ruhmes herum. Wir müssen davon ausgehen, dass diese Höllenorcs Teile der Maschinen für ihre Meister in der Höllenfeuerzitadelle sammeln. Wir müssen sie aufhalten!\n\nSucht im Norden nach den Knochenmalmern, {name}. Sucht sie und tötet sie! Aber seid vorsichtig. Auch wenn diese Orcs einem niederrangigeren Höllenorcklan angehören, sind sie doch genauso stark wie alle grünhäutigen Orcs, die wir bisher getroffen haben!", sourceObjective = "Tötet 20 Orcs der Knochenmalmer und kehrt danach zu Amadi in der Ehrenfeste zurück.", completion = "Sehr gut. Ich bin mir sicher, dass ihr Verlust in der Höllenfeuerzitadelle bemerkt wird. Auch wenn diese dunkle Bastion uns überschattet und unüberwindlich scheint, können wir mit stolzen Taten wie Eurer sicher einen Weg finden, sie zu besiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10483] = { id = 10483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarze Magie", description = "{name}, in unseren Schlachten mit den Höllenorcs des Blutenden Auges haben wir Schmuckstücke mit magischen Kräften bei ihnen gefunden. Diese Orcs haben die Insignien der gefallenen Soldaten der Ehrenfeste gesammelt und verfluchte Talismane aus ihnen gemacht. Wir befürchten, dass die schwarze Magie des Blutenden Auges unsere Insignien in böse Amulette verwandelt haben, die sie gegen uns einsetzen können!\n\nSucht einen solchen Talisman bei den Orcs des Blutenden Auges in Zeth'Gor im Osten. Bringt ihn zu Korporal Eisengrat beim Expeditionsposten nordöstlich von Zeth'Gor.", sourceObjective = "Leutnant Amadi in der Ehrenfeste möchte, dass Ihr einen verfluchten Talisman zu Korporal Eisengrat im Expeditionsposten bringt.", progress = "Bringt Ihr Neues von der Ehrenfeste, {name}? Das ist gut. Unseren Vorgehen gegen die Dämonen und Höllenorcs gehen so langsam die fähigen Kämpfer aus!", completion = "Ah, Ihr habt ein Insigne von den Orcs des Blutenden Auges ergattert? Gut! Es ist eine Schande, dass sie unsere Symbole gegen uns verwenden und sich über unsere Kameraden, die im Kampf gegen diese rothäutigen Bestien gefallen sind, lustig machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[10484] = { id = 10484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchte Talismane", description = "{name}, wir können nicht zulassen, dass die Orcs des Blutenden Auges diese verfluchten Talismane besitzen! Ihr müsst sie für uns beschaffen, damit wir sie zerstören können und so die gefallenen Soldaten, denen sie gehörten, für ihr Opfer ehren.\n\nGeht nach Zeth'Gor, der verfluchten Behausung des Blutenden Auges, und führt Eure grausame Aufgabe durch... Kehrt zu mir zurück, wenn Ihr die Talismane gesammelt habt.", sourceObjective = "Bringt 12 verfluchte Talismane zu Korporal Eisengrat am Expeditionsposten.", progress = "Habt Ihr die Talismane, {name}? Es schmerzt mich zu wissen, dass diese verdammten Orcs die Insignien unserer Soldaten besitzen...", completion = "Danke, {name}. Mein Herz ist voller Trauer, wenn ich diese Talismane betrachte. Sie unterstreichen die zahlreichen Verluste, die wir in der Ehrenfeste gegen die Höllenorcs hinnehmen mussten. Aber es freut mich zu sehen, dass Ihr Erfolg gegen sie hattet. Wenn wir genügend von ihnen töten können, treten wir vielleicht als Sieger aus diesem Krieg hervor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10485] = { id = 10485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr des Blutenden Auges", description = "Ihr habt große Stärke und großes Geschick bewiesen, denn Ihr habt Euch in den Kampf in Zeth'Gor gestürzt und überlebt! Nun wollen wir hoffen, dass das Glück Euch weiterhin hold ist, denn ich muss Euch eine düstere Aufgabe auftragen...\n\nIn der Kaserne von Zeth'Gor sitzt Kriegsherr Morkh und befehligt seine Truppen gegen uns. Seine Taktiken sind genauso schlau wie grausam und ich muss zugeben, dass seine Erfolge bei uns tiefe Wunden geschlagen haben. Deshalb möchte ich Euch bitten, Morkh aus dem Weg zu räumen. Bringt mir seine Rüstung, damit wir sie meinen Soldaten zeigen und ihnen Mut machen können!", sourceObjective = "Bringt Kriegsherr Morkhs zerschmetterte Rüstung zu Korporal Eisengrat im Expeditionsposten.", progress = "Habt Ihr Morkhs zerschmetterte Rüstung? Habt Ihr Euch wieder todesmutig nach Zeth'Gor begeben?", completion = "Ihr habt es geschafft! Morkh ist tot! Jetzt haben wir eine Chance im Kampf gegen die Bestien der Höllenorcs!\n\nVielen Dank, {name}. Eure Hilfe in diesem Krieg ist unermesslich.", sourceObjectiveStatus = "unverified-source-field" }
quests[10486] = { id = 10486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nahende Wildnis", description = "Die Donnerfürsten waren einst ein stolzer Orcklan. Doch dann wurden sie durch Mannoroths Blut in Höllenorcs verwandelt.\n\nVor Kurzem haben wir diesen Orcstützpunkt von den Ogern, die sich in der Klamm unter uns breit gemacht haben, zurückgefordert. Nachdem die Donnerfürsten verschwunden waren, hatten sie hier Einzug gehalten.\n\nWir möchten diesen Ort behalten und Euch gerne bitten, uns dabei zu helfen.\n\nIm Zackengrat im Süden und Westen findet Ihr Blutvergießer, die sich zu einer wahren Seuche entwickeln. Sie fressen und vermehren sich unaufhörlich.\n\nTötet sie und kehrt dann zu mir zurück.", sourceObjective = "Tötet 12 Messerschwingenblutvergießer.", completion = "Das ging schnell. Seid Ihr sicher, dass Ihr so viele getötet habt, wie nötig war?\n\nGut. Es gibt noch eine weitere Aufgabe, bei der wir Eure Hilfe benötigen. Eine weitaus wichtigere.", sourceObjectiveStatus = "unverified-source-field" }
quests[10487] = { id = 10487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenstaub", description = "Vor kurzem hat die Allianz im Westen Einzug gehalten und mit Hilfe ihrer Elfenmagie ein Dorf und einen Hain praktisch aus dem Nichts entstehen lassen. Wir müssen ihre Verteidigung so schwach wie möglich halten, damit sie nicht auch noch ein Rückgrat entwickeln!\n\nIch habe einen Plan, mit dem wir dies und noch mehr erreichen können. Ich möchte, dass Ihr die Brücke nach Südwesten, die über die Blutschlägerklamm in den lebenden Hain führt, überquert.\n\nGreift ihre Siechdrachenverteidigung im lebenden Hain an und bringt mir etwas von dem magischen Staub, der sich manchmal auf ihren Flügeln befindet.", sourceObjective = "Beschafft Euch 4 Einheiten Siechdrachenstaub.", progress = "Es sieht aus, als hätte die Allianz vor, uns überallhin zu folgen. Wir wollen ihnen beweisen, dass ihre Anwesenheit uns keineswegs einschüchtert.\n\nHabt Ihr besorgt, worum ich Euch gebeten habe?", completion = "Ihr habt nicht nur ihre Verteidigung geschwächt. Mit dem Staub werden wir dazu noch unsere eigene Verteidigung gegen die Allianz stärken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10488] = { id = 10488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eigenen schützen", description = "Ich habe aus dem magischen Staub, den Ihr gesammelt habt, eine Salbe hergestellt, die uns bei unserer Verteidigung helfen wird.\n\nAls wir hierher kamen, haben wir ein wundervolles Rudel Terrorwölfe mitgebracht. Sie sind die perfekte Kombination aus Reittier, Wachhund und Freund, aber der Abschaum der Allianz hat begonnen, sie im Zackengrat zu jagen.\n\n{name}, ich möchte, dass Ihr diese Salbe nehmt und sie an unseren Terrorwolffreunden anwendet. Das wird der Allianz eine böse Überraschung bescheren, wenn sie das nächste Mal auf die Jagd geht.\n\nSeid Euch jedoch bewusst, dass einige der Wölfe das vielleicht nicht leiden mögen und Euch angreifen werden.", sourceObjective = "Wendet Gor'dreks Salbe an 5 Terrorwölfen der Donnerfürsten an.", progress = "Wie geht es mit der Verstärkung unserer Terrorwolfverteidigung voran?", completion = "Nun, da Ihr die Wölfe und unsere Verteidigung gestärkt habt, können wir uns wieder einigen tödlicheren Angelegenheiten, wie zum Beispiel den Ogern, zuwenden.\n\nIhr habt uns hier gut geholfen. Wenn Ihr Euch entscheidet zu bleiben, könnten wir auch weiterhin die Dienste von jemandem, der so fähig ist wie Ihr, brauchen.\n\nWie auch immer Ihr Euch entscheiden mögt, Ihr habt meinen Respekt und meine Wertschätzung sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[10489] = { id = 10489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen uralten Baum fällen", description = "GESUCHT!\n\nStarkast Tiefenwurz, Urtum des Krieges und Hauptverteidiger des lebenden Hains südlich von Sylvanaar.\n\nIhr findet ihn, indem Ihr nach Westen geht und die Brücke über der Blutschlägerklamm überquert.\n\nBringt seinen abgeschlagenen Stumpf zu Tor'chunk Zweiklaue.", sourceObjective = "Besorgt Starkast Tiefenwurz' Stumpf.", progress = "Was habt Ihr da? Ihr seid aber stark!", completion = "Starkast Tiefwurz' Stumpf! Habt Ihr ihn selbst gefällt?\n\nSicher habt Ihr das. Wisst Ihr, ein starker {class} wie Ihr es seid, ist genau die Hilfe, nach der Rexxar und ich gesucht haben. Besonders bei den ständigen Problemen, die wir mit den Ogern haben, könnten wir Euch brauchen. Setzt Euch mit mir in Verbindung, wenn Ihr Interesse habt.\n\nNun, dieser Stumpf ist ein stichhaltiger Beweis. Ihr seid hier, um das Kopfgeld einzustreichen, nicht um mit mir zu plaudern. Wohlan, sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[10490] = { id = 10490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist schon eine Weile her, seitdem Ihr das letzte Mal auf die Probe gestellt wurdet. Weissager Nobundo hat nach Euch gefragt.\n\nIhr müsst sehr viel an Erfahrung gewonnen haben, da man Euch nun die Geheimnisse des Elements des Wassers lehren möchte.\n\nIch nehme an, Ihr wisst noch, wie Ihr mit dem Boot von Auberdine an der Dunkelküste in Kalimdor aus zurück zur Exodar kommt? Und Ihr wisst noch, dass Ihr ihn in der Kristallhalle in der Exodar findet, ja?", sourceObjective = "Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", completion = "So treffen wir uns wieder. Ich habe Eure Fortschritte aus der Ferne beobachtet, Schamane, ich bin sehr zufrieden.\n\nEs ist jetzt an der Zeit, dass Ihr mit dem Element des Wassers vertraut werdet. Ihr sollt die Geheimnisse des Wassers erlernen und Euch diesem Wissen widmen, um es mit der Zeit auch beherrschen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[10491] = { id = 10491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "{name}, Weissager Nobundo hat erneut nach Euch verlangt. Es scheint für Euch an der Zeit zu sein, die Geheimnisse der Luft - des noch fehlenden Elements - zu erlernen!\n\nIch bin sehr stolz auf all das, was Ihr bis jetzt erfolgreich gemeistert habt. Ich weiß, dass Euch ein besonderes Schicksal erwartet.\n\nNehmt das Boot von Auberdine an der Dunkelküste in Kalimdor aus. Überquert das verhüllte Meer und sucht den Weissager in der Kristallhalle der Exodar auf der Azurmythosinsel auf.", sourceObjective = "Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel.", completion = "Schließlich kommen wir zu dem letzten der vier großen Elemente, der Luft. Glaubt Ihr weise genug zu sein, um fortzufahren, {name}?", sourceObjectiveStatus = "unverified-source-field" }
